Here is a Node.js function that reads a text file and returns the number of lines it contains.

This solution uses the built-in `fs/promises` module for asynchronous file operations, which is the modern and recommended approach in Node.js.

```javascript
import * as fs from 'fs/promises';
import * as path from 'path';

/**
 * Reads a text file and returns the total number of lines in it.
 *
 * @param {string} filePath The absolute or relative path to the text file.
 * @returns {Promise<number>} A promise that resolves with the number of lines.
 * @throws {Error} Throws an error if the file cannot be read (e.g., file not found, permissions issue).
 */
async function countLinesInFile(filePath: string): Promise<number> {
  try {
    // 1. Read the file content as a string
    const content = await fs.readFile(filePath, { encoding: 'utf8' });

    // 2. Split the content by newline characters.
    // The split method on a string using '\n' will produce an array where
    // the number of elements is one more than the number of lines (if the file
    // doesn't end with a newline) or exactly the number of lines (if it does).
    // A more robust way is to split by '\n' and filter out empty strings,
    // or simply count the occurrences of '\n'.

    // A simple and effective way is to split by '\n' and count the resulting array length.
    // We use .split(/\r?\n/) to handle both Windows (\r\n) and Unix (\n) line endings.
    const lines = content.split(/\r?\n/);

    // 3. Return the count of the lines
    return lines.length;

  } catch (error) {
    console.error(`Error reading file at ${filePath}:`, error instanceof Error ? error.message : error);
    // Re-throw the error so the caller knows the operation failed
    throw new Error(`Failed to count lines in file: ${filePath}`);
  }
}

// --- Example Usage ---

async function main() {
  const fileName = 'sample.txt';

  // 1. Create a dummy file for testing
  try {
    await fs.writeFile(fileName, "This is line one.\nThis is line two.\nAnd this is the third line.");
    console.log(`Successfully created test file: ${fileName}`);

    // 2. Call the function to count the lines
    const lineCount = await countLinesInFile(fileName);
    console.log(`\n--- Result ---`);
    console.log(`The file "${fileName}" has ${lineCount} lines.`);

  } catch (error) {
    console.error("\nOperation failed in main execution:", error);
  } finally {
    // 3. Clean up the dummy file
    try {
      await fs.unlink(fileName);
      console.log(`\nCleaned up test file: ${fileName}`);
    } catch (e) {
      // Ignore error if file doesn't exist during cleanup
    }
  }
}

main();
```

