This implementation handles various forms of whitespace (spaces, tabs, newlines) and uses a regular expression to effectively split the string into words.

```typescript
/**
 * Counts the number of words in a given string.
 * A word is defined as any sequence of non-whitespace characters separated by whitespace.
 *
 * @param text The input string to analyze.
 * @returns The number of words in the string. Returns 0 if the input is null, undefined, or an empty string.
 */
function countWords(text: string | null | undefined): number {
  // 1. Handle null, undefined, or empty string input immediately
  if (!text) {
    return 0;
  }

  // 2. Use a regular expression to split the string by one or more whitespace characters (\s+).
  // The .filter(Boolean) step removes any empty strings that might result from leading/trailing
  // whitespace or multiple spaces between words.
  const words: string[] = text.trim().split(/\s+/).filter(word => word.length > 0);

  // 3. Return the length of the resulting array
  return words.length;
}

// --- Examples ---

