console.log(`"": ${countWords("")}`); // Output: 0
console.log(`"   ": ${countWords("   ")}`); // Output: 0
console.log(`null: ${countWords(null as any)}`); // Output: 0
console.log(`undefined: ${countWords(undefined as any)}`); // Output: 0
