```typescript
/**
 * Converts a snake_case string to camelCase.
 * 
 * @param snakeCaseString The input string in snake_case format (e.g., "my_snake_case_string").
 * @returns The converted string in camelCase format (e.g., "mySnakeCaseString").
 */
export function snakeToCamelCase(snakeCaseString: string): string {
  // 1. Split the string by underscores.
  const parts: string[] = snakeCaseString.split('_');

  // 2. The first part remains as is (lowercase start for camelCase).
  let camelCaseString: string = parts[0];

  // 3. Iterate over the rest of the parts and capitalize the first letter of each.
  for (let i = 1; i < parts.length; i++) {
    const part = parts[i];
    if (part.length > 0) {
      const capitalizedPart = part.charAt(0).toUpperCase() + part.slice(1);
      camelCaseString += capitalizedPart;
    }
  }

  return camelCaseString;
}

// --- Example Usage ---

const example1 = "hello_world";
const camel1 = snakeToCamelCase(example1);
console.log(`Original: ${example1} -> CamelCase: ${camel1}`); // Output: helloWorld

const example2 = "user_profile_data_id";
const camel2 = snakeToCamelCase(example2);
console.log(`Original: ${example2} -> CamelCase: ${camel2}`); // Output: userProfileDataId

const example3 = "singleword";
const camel3 = snakeToCamelCase(example3);
console.log(`Original: ${example3} -> CamelCase: ${camel3}`); // Output: singleword

const example4 = "";
const camel4 = snakeToCamelCase(example4);
console.log(`Original: "${example4}" -> CamelCase: "${camel4}"`); // Output: ""
```

