```typescript
/**
 * Finds the largest number in an array of numbers.
 * 
 * @param numbers An array of numbers to search through.
 * @returns The largest number in the array, or -Infinity if the array is empty.
 */
function findLargestNumber(numbers: number[]): number {
  if (numbers.length === 0) {
    // Return -Infinity for an empty array, as it's the smallest possible number,
    // which is a safe default if you can't throw an error.
    console.warn("Input array is empty. Returning -Infinity.");
    return -Infinity;
  }

  // Use the reduce method to iterate and compare elements
  const largest = numbers.reduce((max: number, current: number) => {
    return current > max ? current : max;
  }, numbers[0]); // Initialize the accumulator with the first element

  return largest;
}

// --- Examples ---

const array1: number[] = [3, 1, 9, 4, 7];
const largest1 = findLargestNumber(array1);
console.log(`The largest number in [${array1}] is: ${largest1}`); // Output: 9

const array2: number[] = [-10, -5, -2, -1];
const largest2 = findLargestNumber(array2);
console.log(`The largest number in [${array2}] is: ${largest2}`); // Output: -1

const array3: number[] = [5];
const largest3 = findLargestNumber(array3);
console.log(`The largest number in [${array3}] is: ${largest3}`); // Output: 5

const arrayEmpty: number[] = [];
const largestEmpty = findLargestNumber(arrayEmpty);
console.log(`The largest number in [] is: ${largestEmpty}`); // Output: -Infinity (and a warning)
```

### Explanation:

