Here is a C function that copies a string without using `strcpy`. We will use `strncpy` (which is often used for this purpose, though it has caveats) or a manual loop for a more fundamental approach.

### Option 1: Using `strncpy` (The Standard Library Approach)

`strncpy` is designed for this, but it has a crucial difference: it doesn't automatically null-terminate the destination string if the source string is longer than the specified size. We must manually ensure null termination.

```c
#include <stdio.h>
#include <string.h>

/**
 * Copies a source string to a destination buffer without using strcpy.
 *
 * @param dest The destination buffer to copy into.
 * @param src The source string to copy from.
 * @param dest_size The maximum size of the destination buffer (including the null terminator).
 * @return A pointer to the destination buffer.
 */
char* safe_strncpy(char* dest, const char* src, size_t dest_size) {
    if (dest == NULL || src == NULL || dest_size == 0) {
        return NULL;
    }

    // Copy at most (dest_size - 1) characters to leave space for the null terminator
    strncpy(dest, src, dest_size - 1);

    // Manually ensure null termination
    dest[dest_size - 1] = '\0';

    return dest;
}

int main() {
    char source[] = "Hello, World!";
    char destination[20];

    printf("Original source: %s\n", source);

    // Test case 1: Source fits within the buffer
    safe_strncpy(destination, source, sizeof(destination));
    printf("Test 1 (Fits): Destination = %s\n", destination);

    // Test case 2: Source is longer than the buffer (will be truncated)
    char long_source[] = "This string is much longer than the buffer.";
    safe_strncpy(destination, long_source, sizeof(destination));
    printf("Test 2 (Truncated): Destination = %s\n", destination);

    return 0;
}
```

### Option 2: Manual Loop (The Fundamental Approach)

This method demonstrates the underlying logic of string copying by iterating through the source string and copying each character one by one, ensuring the destination is null-terminated at the end.

```c
#include <stdio.h>
#include <stddef.h> // For size_t

/**
 * Copies a source string to a destination buffer using a manual loop.
 *
 * @param dest The destination buffer to copy into.
 * @param src The source string to copy from.
 * @param dest_size The maximum size of the destination buffer (including the null terminator).
 * @return A pointer to the destination buffer.
 */
char* manual_copy(char* dest, const char* src, size_t dest_size) {
    if (dest == NULL || src == NULL || dest_size == 0) {
        return NULL;
    }

    size_t i;
    for (i = 0; i < dest_size - 1; i++) {
        dest[i] = src[i];
    }

    // Manually place the null terminator at the end of the copied string
    dest[dest_size - 1] = '\0';

    return dest;
}

