    pub x: f64,
    /// The y-coordinate of the point.
    pub y: f64,
}

impl Point {
    /// Creates a new Point with the given x and y coordinates.
    ///
    /// # Arguments
    ///
    /// * `x` - The x-coordinate.
    /// * `y` - The y-coordinate.
    pub fn new(x: f64, y: f64) -> Self {
        Point { x, y }
    }

    /// Calculates the Euclidean distance between this point and another point.
    ///
    /// The distance is calculated using the formula: sqrt((x2 - x1)^2 + (y2 - y1)^2).
    ///
    /// # Arguments
    ///
    /// * `other` - A reference to the other `Point` to calculate the distance to.
    ///
    /// # Returns
    ///
    /// The distance between the two points as an `f64`.
    pub fn distance_to(&self, other: &Point) -> f64 {
        let dx = other.x - self.x;
        let dy = other.y - self.y;
        (dx * dx + dy * dy).sqrt()
    }
}

fn main() {
    // Create two points
    let p1 = Point::new(1.0, 1.0);
    let p2 = Point::new(4.0, 5.0);

    println!("Point 1: {:?}", p1);
    println!("Point 2: {:?}", p2);

    // Calculate the distance between p1 and p2
    let dist = p1.distance_to(&p2);

    println!("The distance between {:?} and {:?} is: {:.4}", p1, p2, dist);

    // Example 2: Distance to itself (should be 0.0)
    let dist_self = p1.distance_to(&p1);
    println!("The distance from {:?} to itself is: {:.4}", p1, dist_self);
}
```

### Explanation:

1.  **`pub struct Point`**: Defines the structure for our 2D point.
2.  **Fields (`x: f64`, `y: f64`)**: We use `f64` (double-precision floating-point numbers) for the coordinates to allow for precise calculations involving square roots.
